1023|static int ssl_async_start( mbedtls_ssl_context *ssl,
1024|                            mbedtls_x509_crt *cert,
1025|                            ssl_async_operation_type_t op_type,
1026|                            mbedtls_md_type_t md_alg,
1027|                            const unsigned char *input,
1028|                            size_t input_len )
1029|{
1030|    ssl_async_key_context_t *config_data =
1031|        mbedtls_ssl_conf_get_async_config_data( ssl->conf );
1032|    unsigned slot;
1033|    ssl_async_operation_context_t *ctx = NULL;
1034|    const char *op_name = ssl_async_operation_names[op_type];
1035|
1036|    {
1037|        char dn[100];
1038|        if( mbedtls_x509_dn_gets( dn, sizeof( dn ), &cert->subject ) > 0 )
1039|            mbedtls_printf( "Async %s callback: looking for DN=%s\n",
1040|                            op_name, dn );
1041|    }
1042|
1043|    /* Look for a private key that matches the public key in cert.
1044|     * Since this test code has the private key inside Mbed TLS,
1045|     * we call mbedtls_pk_check_pair to match a private key with the
1046|     * public key. */
1047|    for( slot = 0; slot < config_data->slots_used; slot++ )
1048|    {
1049|        if( mbedtls_pk_check_pair( &cert->pk,
1050|                                   config_data->slots[slot].pk,
1051|                                   rng_get, &rng ) == 0 )
1052|            break;
1053|    }
1054|    if( slot == config_data->slots_used )
1055|    {
1056|        mbedtls_printf( "Async %s callback: no key matches this certificate.\n",
1057|                        op_name );
1058|        return( MBEDTLS_ERR_SSL_HW_ACCEL_FALLTHROUGH );
1059|    }
1060|    mbedtls_printf( "Async %s callback: using key slot %u, delay=%u.\n",
1061|                    op_name, slot, config_data->slots[slot].delay );
1062|
1063|    if( config_data->inject_error == SSL_ASYNC_INJECT_ERROR_START )
1064|    {
1065|        mbedtls_printf( "Async %s callback: injected error\n", op_name );
1066|        return( MBEDTLS_ERR_PK_FEATURE_UNAVAILABLE );
1067|    }
1068|
1069|    if( input_len > SSL_ASYNC_INPUT_MAX_SIZE )
1070|        return( MBEDTLS_ERR_SSL_BAD_INPUT_DATA );
1071|
1072|    ctx = mbedtls_calloc( 1, sizeof( *ctx ) );
1073|    if( ctx == NULL )
1074|        return( MBEDTLS_ERR_SSL_ALLOC_FAILED );
1075|    ctx->slot = slot;
1076|    ctx->operation_type = op_type;
1077|    ctx->md_alg = md_alg;
1078|    memcpy( ctx->input, input, input_len );
1079|    ctx->input_len = input_len;
1080|    ctx->remaining_delay = config_data->slots[slot].delay;
1081|    mbedtls_ssl_set_async_operation_data( ssl, ctx );
1082|
1083|    if( ctx->remaining_delay == 0 )
1084|        return( 0 );
1085|    else
1086|        return( MBEDTLS_ERR_SSL_ASYNC_IN_PROGRESS );
